CREATE INDEX IF NOT EXISTS "idx_tags_user_id" ON "public"."tags" USING "btree" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_tasks_pomodoro_id" ON "public"."tasks" USING "btree" ("pomodoro_id");
