-- #region task_templates table
CREATE TABLE IF NOT EXISTS "public"."task_templates" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    "title" text NOT NULL,
    "default_description" text,
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "created_at" timestamp with time zone NOT NULL DEFAULT now()
);
ALTER TABLE "public"."task_templates" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."task_templates_tags" (
    "template_id" uuid NOT NULL REFERENCES public.task_templates(id) ON DELETE CASCADE,
    "tag_id" bigint NOT NULL REFERENCES public.tags(id) ON DELETE CASCADE,
    PRIMARY KEY ("template_id", "tag_id")
);
ALTER TABLE "public"."task_templates_tags" OWNER TO "postgres";
-- #endregion

-- #region TIME_SESSIONS and FLOWS tables
CREATE TABLE IF NOT EXISTS "public"."time_sessions" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "mode" public.time_measurement_mode NOT NULL,
    "state" public.pomodoro_state NOT NULL DEFAULT 'idle',
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "timelapse" integer NOT NULL DEFAULT 0,
    "toggle_timeline" jsonb,
    "created_at" timestamp with time zone NOT NULL DEFAULT now()
);
ALTER TABLE "public"."time_sessions" OWNER TO "postgres";

CREATE UNIQUE INDEX idx_unique_active_time_session ON "public"."time_sessions" ("user_id", "mode") WHERE state NOT IN ('finished', 'skipped');

CREATE TABLE IF NOT EXISTS "public"."flows" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "time_session_id" bigint NOT NULL REFERENCES public.time_sessions(id) ON DELETE CASCADE,
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "jornada_bloque" text NOT NULL,
    "jornada_limit_at" timestamp with time zone,
    "created_at" timestamp with time zone NOT NULL DEFAULT now()
);
ALTER TABLE "public"."flows" OWNER TO "postgres";
-- #endregion

-- #region OKR objectives and key_results
CREATE TYPE public.metric_category AS ENUM (
    'COUNT_ATOMIC',
    'TIME_INVESTMENT',
    'KNOWLEDGE_DENSITY',
    'QUALITY_SCORE'
);

CREATE TABLE IF NOT EXISTS "public"."objectives" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "title" text NOT NULL,
    "description" text,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
ALTER TABLE "public"."objectives" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."key_results" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    "objective_id" uuid NOT NULL REFERENCES public.objectives(id) ON DELETE CASCADE,
    "title" text NOT NULL,
    "target_value" numeric NOT NULL,
    "current_value" numeric DEFAULT 0 NOT NULL,
    "metric_type" public.metric_category NOT NULL,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
ALTER TABLE "public"."key_results" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."key_result_tags" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    "key_result_id" uuid NOT NULL REFERENCES public.key_results(id) ON DELETE CASCADE,
    "tag_id" bigint NOT NULL REFERENCES public.tags(id) ON DELETE CASCADE,
    "weight" numeric DEFAULT 1.0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    UNIQUE ("key_result_id", "tag_id")
);
ALTER TABLE "public"."key_result_tags" OWNER TO "postgres";
-- #endregion

-- #region Zettelkasten notes table
CREATE TABLE IF NOT EXISTS "public"."notes" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "storage_path" text NOT NULL,
    "title" text,
    "frontmatter" jsonb,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
    UNIQUE ("user_id", "storage_path")
);
ALTER TABLE "public"."notes" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."notes_tags" (
    "note_id" uuid NOT NULL REFERENCES public.notes(id) ON DELETE CASCADE,
    "tag_id" bigint NOT NULL REFERENCES public.tags(id) ON DELETE CASCADE,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    PRIMARY KEY ("note_id", "tag_id")
);
ALTER TABLE "public"."notes_tags" OWNER TO "postgres";
-- #endregion

-- #region scheduled_notifications table (declarative definition with action_type)
CREATE TABLE IF NOT EXISTS "public"."notification_templates" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    "name" text NOT NULL,
    "title" text NOT NULL,
    "body" text NOT NULL,
    "icon" text,
    "link" text,
    "created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);
ALTER TABLE "public"."notification_templates" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."scheduled_notifications" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "template_id" uuid REFERENCES public.notification_templates(id) ON DELETE SET NULL,
    "rrule" text,
    "scheduled_at" timestamp with time zone NOT NULL,
    "last_executed_at" timestamp with time zone,
    "timezone" text NOT NULL DEFAULT 'UTC',
    "payload_override" jsonb,
    "status" text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'completed')),
    "action_type" text DEFAULT 'NONE' CHECK (action_type IN ('NONE', 'CREATE_TASK', 'REVIEW_NOTE', 'CREATE_LOG', 'AI_ATOMIZE')),
    "created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);
ALTER TABLE "public"."scheduled_notifications" OWNER TO "postgres";

CREATE INDEX IF NOT EXISTS "ix_scheduled_notifications_scheduled_at" ON "public"."scheduled_notifications" USING btree ("scheduled_at");
CREATE INDEX IF NOT EXISTS "ix_scheduled_notifications_status" ON "public"."scheduled_notifications" USING btree ("status");
CREATE INDEX IF NOT EXISTS "ix_scheduled_notifications_user_id" ON "public"."scheduled_notifications" USING btree ("user_id");

GRANT ALL ON TABLE "public"."scheduled_notifications" TO "anon";
GRANT ALL ON TABLE "public"."scheduled_notifications" TO "authenticated";
GRANT ALL ON TABLE "public"."scheduled_notifications" TO "service_role";

GRANT ALL ON TABLE "public"."notification_templates" TO "anon";
GRANT ALL ON TABLE "public"."notification_templates" TO "authenticated";
GRANT ALL ON TABLE "public"."notification_templates" TO "service_role";
-- #endregion

-- #region inbox_actions table
CREATE TABLE IF NOT EXISTS "public"."inbox_actions" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "source_notification_id" uuid REFERENCES public.scheduled_notifications(id) ON DELETE SET NULL,
    "title" text NOT NULL,
    "description" text,
    "action_type" text DEFAULT 'NONE'
        CHECK (action_type IN ('NONE', 'CREATE_TASK', 'REVIEW_NOTE', 'CREATE_LOG', 'AI_ATOMIZE', 'OKR_PROGRESS')),
    "action_payload" jsonb DEFAULT '{}',
    "status" text DEFAULT 'pending'
        CHECK (status IN ('pending', 'completed', 'dismissed')),
    "priority" int DEFAULT 1,
    "execution_count" int DEFAULT 0,
    "created_at" timestamptz DEFAULT now(),
    "completed_at" timestamptz
);
ALTER TABLE "public"."inbox_actions" OWNER TO "postgres";

CREATE INDEX IF NOT EXISTS "ix_inbox_actions_user_id" ON "public"."inbox_actions" USING btree ("user_id");
CREATE INDEX IF NOT EXISTS "ix_inbox_actions_status" ON "public"."inbox_actions" USING btree ("status");

GRANT ALL ON TABLE "public"."inbox_actions" TO "anon";
GRANT ALL ON TABLE "public"."inbox_actions" TO "authenticated";
GRANT ALL ON TABLE "public"."inbox_actions" TO "service_role";
-- #endregion

